MagickBooleanType DecodeDXT3(Image *image, DDSInfo *dds_info, ExceptionInfo *exception) {
    ssize_t block_width, block_height, x, y, block_x, block_y;
    unsigned char alpha_data[16];
    unsigned short color_codes[4];
    size_t i, j;
    MagickBooleanType result;

    block_width = (dds_info->width + 3) / 4;
    block_height = (dds_info->height + 3) / 4;

    for (block_y = 0; block_y < block_height; block_y++) {
        for (block_x = 0; block_x < block_width; block_x++) {
            for (i = 0; i < 16; i++) {
                if (ReadBlob(image, sizeof(unsigned char), alpha_data + i) != sizeof(unsigned char))
                    return MagickFalse;
            }

            for (i = 0; i < 4; i++) {
                if (ReadBlob(image, sizeof(unsigned short), &color_codes[i]) != sizeof(unsigned short))
                    return MagickFalse;
            }

            for (y = 0; y < 4; y++) {
                for (x = 0; x < 4; x++) {
                    size_t index = (y * 4 + x);
                    ssize_t px = block_x * 4 + x;
                    ssize_t py = block_y * 4 + y;

                    if (px >= (ssize_t)dds_info->width || py >= (ssize_t)dds_info->height)
                        continue;

                    if (index >= 16)
                        continue;

                    unsigned short code = color_codes[alpha_data[index] & 0x0F];
                    Quantum r = ClampToQuantum((Quantum)((code & 0x1F) * 8));
                    Quantum g = ClampToQuantum((Quantum)(((code >> 5) & 0x1F) * 8));
                    Quantum b = ClampToQuantum((Quantum)(((code >> 10) & 0x1F) * 8));
                    SetPixelRed(image, r, GetPixelInfoPixel(image, x, y, image->pixels));
                    SetPixelGreen(image, g, GetPixelInfoPixel(image, x, y, image->pixels));
                    SetPixelBlue(image, b, GetPixelInfoPixel(image, x, y, image->pixels));
                }
            }
        }
    }

    result = SkipMipmaps(image, dds_info, exception);

    return result;
}

