    for (y = 0; y < dds_info->height; y += 4) {
        for (x = 0; x < dds_info->width; x += 4) {
            for (block_width = 0; block_width < 4; block_width++) {
                for (block_height = 0; block_height < 4; block_height++) {
                    if (fread(alpha, sizeof(unsigned int), 16, dds_info->file) != 16) {
                        result = MagickFalse;
                        break;
                    }
                    if (fread(color, sizeof(unsigned short), 16, dds_info->file) != 16) {
                        result = MagickFalse;
                        break;
                    }
                    for (block_width = 0; block_width < 4; block_width++) {
                        for (block_height = 0; block_height < 4; block_height++) {
                            red1 = (color[block_width * 4 + block_height] >> 11) & 0x1F;
                            green1 = (color[block_width * 4 + block_height] >> 5) & 0x3F;
                            blue1 = (color[block_width * 4 + block_height] >> 0) & 0x1F;
                            red1 = ((red1 * 255) + 24) / 31;
                            green1 = ((green1 * 255) + 31) / 63;
                            blue1 = ((blue1 * 255) + 24) / 31;
                            alpha_value = (Quantum) alpha[block_width * 4 + block_height];
                            q = GetPixelCache(image, x + block_width, y + block_height);
                            q[0] = blue1;
                            q[1] = green1;
